# connected components of each nonzero color
def comps(g,col):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; out=[]
    for h in range(H):
        for w in range(W):
            if g[h][w]==col and not seen[h][w]:
                c=[[h,w]]; stack=[(h,w)]; seen[h][w]=True
                while stack:
                    y,x=stack.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                out.append(c)
    return out
