def shape(cs):
    ys=[x[0] for x in cs]; xs=[x[1] for x in cs]
    return (max(ys)-min(ys)+1, max(xs)-min(xs)+1, tuple(sorted((y-min(ys),x-min(xs)) for y,x in cs)))
